// When you run: mvn clean package

// Step 1: clean lifecycle
// - Deletes target/ directory

// Step 2: default lifecycle phases execute in order:
public class OrderService {
    // Phase: validate - checks pom.xml structure
    // Phase: compile - javac compiles this to target/classes/

    public Order createOrder(String item) {
        return new Order(item);
    }
}

// Phase: test - runs this test class
class OrderServiceTest {
    @Test
    void shouldCreateOrder() {
        var service = new OrderService();
        var order = service.createOrder("Laptop");
        assertNotNull(order);
    }
}

// Phase: package - creates target/order-service-1.0.jar
// Phases install and deploy would copy/upload the JAR
